test = {(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# tile candidates are all full 2x2 and 3 of cells in local 2x2
from itertools import combinations
cand=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for n in [3,4]:
   for sub in combinations(sorted(box),n):
    s=frozenset(sub)
    if s<=test: cand.append(s)
# exact-cover recurse
bycell={p:[s for s in cand if p in s] for p in test}
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen); return
 p=min(rem,key=lambda x:sum(s<=rem for s in bycell[x]))
 for s in bycell[p]:
  if s<=rem: rec(rem-s,chosen+[s])
rec(set(test),[])
len(sol), [len(x) for x in sol[:5]]
